  // Helper to match candidate
  function findCandidate(bodyKey, siteId, lat, lon) {
    const rankingKey = (bodyKey.toLowerCase() === "mars" || bodyKey.toLowerCase() === "marte") ? "martian_ranking" : "lunar_ranking";
    const list = CATALOG[rankingKey] || [];
    if (siteId) {
      const clean = siteId.toLowerCase();
      for (const c of list) {
        if (c.id.toLowerCase() === clean || c.id.toLowerCase().includes(clean) || clean.includes(c.id.toLowerCase())) {
          return c;
        }
      }
    }
    if (lat !== undefined && lon !== undefined) {
      let best = null, minDist = Infinity;
      for (const c of list) {
        const d = Math.hypot(c.lat - lat, c.lon - lon);
        if (d < minDist) { minDist = d; best = c; }
      }
      if (best && minDist < 1.0) return best;
    }
    return list[0] || null;
  }

